import{_ as t,o as i,c as e,a2 as r}from"./chunks/framework.BqNd1sPY.js";const h=JSON.parse('{"title":"D07：模型如何生成文字","description":"","frontmatter":{},"headers":[],"relativePath":"01-14天理论课/D07-模型如何生成文字.md","filePath":"01-14天理论课/D07-模型如何生成文字.md"}'),o={name:"01-14天理论课/D07-模型如何生成文字.md"};function n(s,a,l,d,c,k){return i(),e("div",null,[...a[0]||(a[0]=[r('<h1 id="d07-模型如何生成文字" tabindex="-1">D07：模型如何生成文字 <a class="header-anchor" href="#d07-模型如何生成文字" aria-label="Permalink to &quot;D07：模型如何生成文字&quot;">​</a></h1><h2 id="今日目标" tabindex="-1">今日目标 <a class="header-anchor" href="#今日目标" aria-label="Permalink to &quot;今日目标&quot;">​</a></h2><p>理解自回归生成循环、温度、top-k、top-p、<a href="/LLMTrain/05-速查表/术语速查#term-kv-cache" class="wiki-term" data-wiki-title="KV Cache" data-wiki-summary="自回归生成时缓存历史 token 的 Key/Value，避免每一步重复计算。" data-wiki-misconception="KV Cache 主要用于降低训练显存。">KV Cache</a> 和停止条件。</p><h2 id="一步一步生成" tabindex="-1">一步一步生成 <a class="header-anchor" href="#一步一步生成" aria-label="Permalink to &quot;一步一步生成&quot;">​</a></h2><p>提示词编码为 <code>[12, 8, 31]</code> 后，模型输出下一个 <a href="/LLMTrain/05-速查表/术语速查#term-token" class="wiki-term" data-wiki-title="token" data-wiki-summary="文本经过分词规则得到的离散单元，随后会映射成整数 ID。" data-wiki-misconception="token 必然等于一个字或一个完整单词。">token</a> 的 <a href="/LLMTrain/05-速查表/术语速查#term-logits" class="wiki-term" data-wiki-title="logits" data-wiki-summary="softmax 之前的任意实数分数，用来比较各候选 token。" data-wiki-misconception="logits 已经是概率或正确率。">logits</a>。经过选择得到 ID <code>5</code>，新序列变成 <code>[12, 8, 31, 5]</code>，再预测下一步，直到遇到停止 <a href="/LLMTrain/05-速查表/术语速查#term-token" class="wiki-term" data-wiki-title="token" data-wiki-summary="文本经过分词规则得到的离散单元，随后会映射成整数 ID。" data-wiki-misconception="token 必然等于一个字或一个完整单词。">token</a>、长度上限或外部停止规则。</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>上下文 -&gt; logits -&gt; 选择 token -&gt; 追加 -&gt; 再运行</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>模型不是先在内部写完整答案再一次显示；流式界面只是把逐步生成的结果尽早发送。</p><h2 id="四种常见选择" tabindex="-1">四种常见选择 <a class="header-anchor" href="#四种常见选择" aria-label="Permalink to &quot;四种常见选择&quot;">​</a></h2><ul><li><strong>Greedy</strong>：每步选最高概率。确定性强，但不保证整段序列全局最优。</li><li><strong>Temperature</strong>：先用温度缩放 <a href="/LLMTrain/05-速查表/术语速查#term-logits" class="wiki-term" data-wiki-title="logits" data-wiki-summary="softmax 之前的任意实数分数，用来比较各候选 token。" data-wiki-misconception="logits 已经是概率或正确率。">logits</a>。较低通常更集中，较高通常更多样。</li><li><strong>Top-k</strong>：只在概率最高的 k 个候选中选择。</li><li><strong>Top-p</strong>：取累计概率达到阈值的最小候选集合，再从中选择。</li></ul><p>top-k、top-p 和温度可以组合。它们改变输出分布，不能把事实错误自动变正确。</p><h2 id="手工模拟" tabindex="-1">手工模拟 <a class="header-anchor" href="#手工模拟" aria-label="Permalink to &quot;手工模拟&quot;">​</a></h2><p>候选概率为：</p><table tabindex="0"><thead><tr><th><a href="/LLMTrain/05-速查表/术语速查#term-token" class="wiki-term" data-wiki-title="token" data-wiki-summary="文本经过分词规则得到的离散单元，随后会映射成整数 ID。" data-wiki-misconception="token 必然等于一个字或一个完整单词。">token</a></th><th style="text-align:right;">概率</th></tr></thead><tbody><tr><td>蓝</td><td style="text-align:right;">0.50</td></tr><tr><td>晴</td><td style="text-align:right;">0.30</td></tr><tr><td>灰</td><td style="text-align:right;">0.15</td></tr><tr><td>雨</td><td style="text-align:right;">0.05</td></tr></tbody></table><ul><li>Greedy 选“蓝”。</li><li>top-k=2 只保留“蓝、晴”，随后重新归一化。</li><li>top-p=0.8 时，排序后“蓝、晴”的累计概率刚好为 0.8。</li></ul><h2 id="kv-cache-为什么有用" tabindex="-1">KV Cache 为什么有用 <a class="header-anchor" href="#kv-cache-为什么有用" aria-label="Permalink to &quot;KV Cache 为什么有用&quot;">​</a></h2><p>生成第 100 个 <a href="/LLMTrain/05-速查表/术语速查#term-token" class="wiki-term" data-wiki-title="token" data-wiki-summary="文本经过分词规则得到的离散单元，随后会映射成整数 ID。" data-wiki-misconception="token 必然等于一个字或一个完整单词。">token</a> 时，前 99 个位置的 Key/Value 在每层已经算过。<a href="/LLMTrain/05-速查表/术语速查#term-kv-cache" class="wiki-term" data-wiki-title="KV Cache" data-wiki-summary="自回归生成时缓存历史 token 的 Key/Value，避免每一步重复计算。" data-wiki-misconception="KV Cache 主要用于降低训练显存。">KV Cache</a> 保存这些中间结果，避免每步全部重算。它用内存换速度，所需内存随层数、序列长度、KV 头数、头维度、<a href="/LLMTrain/05-速查表/术语速查#term-batch" class="wiki-term" data-wiki-title="batch" data-wiki-summary="一次前向与反向计算共同处理的一组样本。" data-wiki-misconception="一个 batch 必然等于一次优化器更新或整个数据集。">batch</a> 和数据类型变化。</p><h2 id="幻觉从哪里来" tabindex="-1">幻觉从哪里来 <a class="header-anchor" href="#幻觉从哪里来" aria-label="Permalink to &quot;幻觉从哪里来&quot;">​</a></h2><p>训练目标要求预测可能的下一个 <a href="/LLMTrain/05-速查表/术语速查#term-token" class="wiki-term" data-wiki-title="token" data-wiki-summary="文本经过分词规则得到的离散单元，随后会映射成整数 ID。" data-wiki-misconception="token 必然等于一个字或一个完整单词。">token</a>，不要求每句话都经过外部事实核验。数据矛盾、<a href="/LLMTrain/05-速查表/术语速查#term-context" class="wiki-term" data-wiki-title="context" data-wiki-summary="模型本次计算能够看到的 token 序列。" data-wiki-misconception="放进上下文的信息已经永久写入模型参数。">上下文</a>不足、采样、任务分布变化都会导致自信但错误的回答。<a href="/LLMTrain/05-速查表/术语速查#term-rag" class="wiki-term" data-wiki-title="RAG" data-wiki-summary="先检索外部资料，再把相关片段放进上下文辅助生成。" data-wiki-misconception="检索到资料就能保证资料和答案都真实。">RAG</a>、工具和验证器可以降低部分风险，但不能给出无条件保证。</p><h2 id="今日验收" tabindex="-1">今日验收 <a class="header-anchor" href="#今日验收" aria-label="Permalink to &quot;今日验收&quot;">​</a></h2><ol><li>Greedy 是否保证整段概率最高？</li><li>提高温度通常如何改变分布？</li><li><a href="/LLMTrain/05-速查表/术语速查#term-kv-cache" class="wiki-term" data-wiki-title="KV Cache" data-wiki-summary="自回归生成时缓存历史 token 的 Key/Value，避免每一步重复计算。" data-wiki-misconception="KV Cache 主要用于降低训练显存。">KV Cache</a> 保存的是模型全部<a href="/LLMTrain/05-速查表/术语速查#term-parameter" class="wiki-term" data-wiki-title="parameter" data-wiki-summary="模型中由训练确定的数字；训练时只有未冻结的参数会被更新。" data-wiki-misconception="一个参数对应一条可直接读取的事实。">参数</a>吗？</li><li>为什么降低温度不能根治幻觉？</li></ol><p>下一课：<a href="./D08-训练数据与分词器">D08：训练数据与分词器</a></p>',21)])])}const p=t(o,[["render",n]]);export{h as __pageData,p as default};
